The evidence points to one root cause: an HTTP-layer slowdown on ts-travel-service's outgoing `left_tickets` calls to ts-seat-service. Its effect reaches the user through route-plan, travel-plan and preserve.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms, approx_quantile(s.duration,0.95)/1e6 server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC", "claim": "Travel's client calls to seat left_tickets take ~4.8s p50 while seat's server spans take ~24ms; other paths stay fast."},
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC", "claim": "Before the incident the same travel-to-seat left_tickets calls had client p50 about 27ms, close to server time."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, sum(value) s, max(value) mx FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND ((attr_source LIKE '%ts-travel-service%' AND attr_destination LIKE '%ts-seat%') OR (attr_source LIKE '%ts-seat%' AND attr_destination LIKE '%ts-travel-service%')) GROUP BY ALL", "claim": "Travel-seat TCP flag counts stay in line with normal, with no drop metrics, so the wire is healthy; the delay is inside the HTTP layer."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.5)/1e6 callee_server_p50_ms, approx_quantile(s.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL", "claim": "Route-plan calls to travel-service have server p95 near 29s in the abnormal period."}
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL", "claim": "Travel-plan calls to route-plan have server p95 near 29s, inheriting the travel-service delay."}
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.5)/1e6 callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL", "claim": "Preserve calls to travel-service take about 9.7s, so preserve inherits the travel delay."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL", "claim": "Dashboard calls to travel-plan see server p95 near 30s, reaching the user-facing tier."}
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL", "claim": "Dashboard calls to preserve show server p95 above 11s in the abnormal period."}
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY ALL", "claim": "Dashboard calls to travel-service have server p95 around 31s, so the user trips path is slow."}
      ]
    }
  ]
}
```

